        check("fillTemplate(\"no placeholders\", \"user\", \"Ada\")", "no placeholders", TemplateFiller.fillTemplate("no placeholders", "user", "Ada"));
        check("fillTemplate(\"{a}{b}\", \"a\", \"1\")", "1{b}", TemplateFiller.fillTemplate("{a}{b}", "a", "1"));
        check("fillTemplate(\"{x} + {x} = 2{x}\", \"x\", \"1\")", "1 + 1 = 21", TemplateFiller.fillTemplate("{x} + {x} = 2{x}", "x", "1"));
        check("fillTemplate(\"\", \"x\", \"y\")", "", TemplateFiller.fillTemplate("", "x", "y"));
